import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第二册：实践与进步 · Lesson 91 Three men in a basket","description":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 91 Three men in a basket","description":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 90 What's for supper?","link":"/life/english/new-concept/book-2/unit-04/lesson-090"},"next":{"text":"第二册：实践与进步 · Lesson 92 Asking for trouble","link":"/life/english/new-concept/book-2/unit-04/lesson-092"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 90 What's for supper?","link":"/life/english/new-concept/book-2/unit-04/lesson-090"},"next":{"text":"第二册：实践与进步 · Lesson 92 Asking for trouble","link":"/life/english/new-concept/book-2/unit-04/lesson-092"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-091.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-091.md"}`),o={name:"life/english/new-concept/book-2/unit-04/lesson-091.md"};function l(r,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-91-three-men-in-a-basket" tabindex="-1">第二册：实践与进步 · Lesson 91 Three men in a basket <a class="header-anchor" href="#第二册-实践与进步-·-lesson-91-three-men-in-a-basket" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 91 Three men in a basket&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>热气球旅程同时涉及高度、风向和落地点，观察者视角决定叙述重点；练习过去进行。本课的语言观察是：were drifting 描述风中持续漂移，noticed 是其中发生的发现。漂移方向可以改变，单句不保证最终抵达观察到的田地。完成学习后，请写三句空中观景或登高经历，包含背景、发现与最终位置。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>balloon</td><td>/bəˈluːn/</td><td>n.</td><td>气球</td><td>a hot-air balloon</td></tr><tr><td>basket</td><td>/ˈbɑːskɪt/</td><td>n.</td><td>篮子</td><td>a wicker basket</td></tr><tr><td>height</td><td>/haɪt/</td><td>n.</td><td>高度</td><td>at a great height</td></tr><tr><td>pilot</td><td>/ˈpaɪlət/</td><td>n.</td><td>飞行员</td><td>an experienced pilot</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at a height of — 在……高度，后接数值单位</li><li>come down — 下降，也可表示价格下降，需看语境</li></ul><h2 id="语法讲解-过去进行时与叙事背景" tabindex="-1">语法讲解：过去进行时与叙事背景 <a class="header-anchor" href="#语法讲解-过去进行时与叙事背景" aria-label="Permalink to &quot;语法讲解：过去进行时与叙事背景&quot;">​</a></h2><p>过去进行时由 was/were 加动词 -ing 构成，描述过去某个时刻正在展开的活动。它常与一般过去时配合：进行时给出背景，过去式指出发生在背景中的事件。when 与 while 的选择取决于从句表达瞬间还是过程，不能把两者当作机械的时态开关。两个同时持续的活动也可都用进行时，而状态动词往往仍用简单时态。本课应用：were drifting 描述风中持续漂移，noticed 是其中发生的发现。漂移方向可以改变，单句不保证最终抵达观察到的田地。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We were drifting over the fields when the pilot noticed a clear landing area.</p></blockquote><p>我们正飘过田野时，飞行员发现了一块空旷的降落区。</p><p>were drifting 为背景，when 引出 noticed；a clear landing area 首次引入新地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>连读 drifting over，重读 well away，区分观察区域与实际落地点。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We were drifting over the fields when the pilot noticed a clear landing area. He checked the wind once more. We landed beyond a fence, well away from the road.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句空中观景或登高经历，包含背景、发现与最终位置。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：were drifting 为背景，when 引出 noticed；a clear landing area 首次引入新地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 drift：We were ___ over the fields.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> drifting</p><p><strong>解析：</strong> 过去进行时为 were 加 -ing。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>他们落在公路边吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. They landed well away from the road.</p><p><strong>解析：</strong> well away from 表相当远离，而非紧靠。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“在五十米的高度”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at a height of fifty metres</p><p><strong>解析：</strong> 高度使用 at a height of 加数值与单位。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去进行时与叙事背景。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-090">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-092">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(o,[["render",l]]);export{u as __pageData,f as default};
